import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158561894555',sleep=ms=>new Promise(r=>setTimeout(r,ms));
const expected={
'products-built-for-the-line-u-s-army':9,
'products-built-for-the-line-u-s-navy':8,
'products-built-for-the-line-u-s-air-force':10,
'products-built-for-the-line-u-s-marine-corps':12,
'products-built-for-the-line-u-s-coast-guard':7,
'products-built-for-the-line-u-s-space-force':5
};
const browser=await chromium.launch({headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});const failures=[],results=[];
async function ready(p){await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:60000});await p.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible',timeout:20000});await sleep(800)}
for(const [root,count] of Object.entries(expected)){
 const p=await context.newPage();try{await p.goto(`${BASE}/collections/${root}?preview_theme_id=${THEME}`,{waitUntil:'domcontentloaded',timeout:90000});await ready(p);const cats=await p.evaluate(()=>{const d=[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group')].find(x=>(x.querySelector(':scope>summary')?.textContent||'').trim()==='Shop by Category');return d?[...d.querySelectorAll('.sq-refine-v3-choice')].map(c=>{const i=c.querySelector('input');return{label:(c.querySelector('span')?.textContent||'').trim(),kind:i?.dataset.kind||'',target:i?.dataset.target||''}}):[]});if(cats.length!==count)failures.push(`${root}: expected ${count} categories got ${cats.length}`);const checks=[];for(const c of cats){const u=new URL(c.target,BASE);if(c.kind!=='structural')failures.push(`${root}/${c.label}: kind=${c.kind}`);if(u.searchParams.get('sq_root')!==root)failures.push(`${root}/${c.label}: wrong sq_root`);u.searchParams.set('preview_theme_id',THEME);const q=await context.newPage();try{await q.goto(u.toString(),{waitUntil:'domcontentloaded',timeout:90000});await ready(q);const d=await q.evaluate(()=>{const main=document.querySelector('#MainContent'),grid=main?.querySelector('.sq-refine-v3-results .product-grid'),cards=grid?[...grid.querySelectorAll(':scope>.product-grid__item')].filter(x=>x.querySelector('a[href*="/products/"]')):[];const category=[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group')].find(x=>(x.querySelector(':scope>summary')?.textContent||'').trim()==='Shop by Category');const checked=category?[...category.querySelectorAll('.sq-refine-v3-choice')].filter(x=>x.querySelector('input:checked')).map(x=>(x.querySelector('span')?.textContent||'').trim()):[];return{ready:main?.dataset.sqRefineV3Ready==='true',error:main?.dataset.sqRefineV3Error||'',cards:cards.length,checked,legacy:[...main.querySelectorAll('[class*="button-tree"],[class*="root-categories"],[class*="third-level"],[class*="branch-grid"],[class*="type-grid"],[class*="program-tree"],[class*="category-grid"],[class*="navigation-grid"],.sqbfl')].filter(e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&!e.closest('.sq-refine-v3-sidebar,.sq-refine-v3-results')}).length}});checks.push({label:c.label,path:u.pathname,...d});if(!d.ready||d.error||d.cards<1)failures.push(`${root}/${c.label}: ready=${d.ready} error=${d.error} cards=${d.cards}`);if(!d.checked.includes(c.label))failures.push(`${root}/${c.label}: selected category not checked`);if(d.legacy)failures.push(`${root}/${c.label}: legacy=${d.legacy}`)}catch(e){failures.push(`${root}/${c.label}: ${String(e)}`)}finally{await q.close()}}results.push({root,categories:cats.map(x=>x.label),checks});console.log('PBTL_ROOT '+JSON.stringify(results.at(-1)))}catch(e){failures.push(`${root}: ${String(e)}`)}finally{await p.close()}}
console.log('PBTL_CATEGORY_SUMMARY '+JSON.stringify({roots:results.length,failures}));await browser.close();if(failures.length)process.exit(1);
